#include <stdio.h>
#include <stdlib.h>

long long fib(int n) {
    if (n <= 1) return 1;
    long long a = 1, b = 1;
    for (int i = 2; i <= n; i++) {
        long long temp = a + b;
        a = b;
        b = temp;
    }
    return b;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s N\\n", argv[0]);
        return 1;
    }
    int n = atoi(argv[1]);
    printf("%lld\\n", fib(n));
    return 0;
}

